add_filter( 'manage_edit-shop_order_columns', 'perfectpixel_orders_products_column' );
add_filter( 'manage_woocommerce_page_wc-orders_columns', 'perfectpixel_orders_products_column' );
add_action( 'manage_shop_order_posts_custom_column', 'perfectpixel_orders_products_column_value', 10, 2 );
add_action( 'manage_woocommerce_page_wc-orders_custom_column', 'perfectpixel_orders_products_column_value', 10, 2 );

function perfectpixel_orders_products_column( $columns ) {
	$new = array();
	foreach ( $columns as $key => $label ) {
		$new[ $key ] = $label;
		if ( 'order_number' === $key ) {
			$new['perfectpixel_products'] = '{{orders_products_column_title}}';
		}
	}
	return $new;
}

function perfectpixel_orders_products_column_value( $column, $post_or_order ) {
	if ( 'perfectpixel_products' !== $column ) {
		return;
	}
	$order = $post_or_order instanceof WC_Order ? $post_or_order : wc_get_order( $post_or_order );
	if ( ! $order ) {
		return;
	}
	$lines = array();
	foreach ( $order->get_items() as $item ) {
		$lines[] = esc_html( $item->get_quantity() . ' × ' . $item->get_name() );
	}
	echo '<small>' . implode( '<br>', $lines ) . '</small>';
}
